package net.officefloor.hq.app.person;

import java.util.Comparator;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.plan.Plan;
import net.officefloor.hq.app.plan.PlanRepository;
import net.officefloor.hq.app.pool.PoolMember;
import net.officefloor.hq.app.pool.PoolMemberRepository;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.rollup.Rollups;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.statement.StatementRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * Merging a person into another on the sheet: a steward only. The merged person's claims move to the
 * other, numbers and dates kept, listed after the other's own in the order they were added, each
 * losing any figure a statement bound. Their name and aliases become aliases of the other; their
 * patrons are added to the other's (not the other themselves, no repeats); anyone naming them as a
 * patron names the other instead (no repeats); their pool memberships move to the other, shares added
 * where the other is already a member; their plans become the other's. Their statements, holds, watchers and contact are dropped, and
 * they leave the sheet.
 */
@Service
public class MergeService {

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final StatementRepository statements;
    private final WatchRepository watches;
    private final PoolMemberRepository poolMembers;
    private final PlanRepository plans;
    private final RoleService roles;
    private final SheetService sheets;
    private final Rollups rollups;
    private final Audit audit;

    public MergeService(PersonRepository people, ClaimRepository claims, StatementRepository statements,
            WatchRepository watches, PoolMemberRepository poolMembers, PlanRepository plans, RoleService roles, SheetService sheets,
            Rollups rollups, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.statements = statements;
        this.watches = watches;
        this.poolMembers = poolMembers;
        this.plans = plans;
        this.roles = roles;
        this.sheets = sheets;
        this.rollups = rollups;
        this.audit = audit;
    }

    /**
     * Merge a person into another on the sheet: the person merged into, as the store holds them after.
     * Refused unless the user is a steward, for the person themselves, and when either is retired.
     */
    @Transactional
    public Person merge(String sheetId, String user, long personId, long intoId) {
        sheets.lock(sheetId);
        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward merges people.");
        }
        Person from = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        Person into = people.findByIdAndSheetId(intoId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        if (from.getId().equals(into.getId())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be merged into themselves.");
        }
        if (from.getRetiredFrom() != null || into.getRetiredFrom() != null) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A retired person cannot be merged.");
        }
        Rollups.Rollup before = rollups.take(sheetId);

        // Their claims, in the order they were added, move to the other unbound.
        List<Claim> moved = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, from.getId()).stream()
                .sorted(Comparator.comparing(Claim::getId)).toList();
        for (Claim claim : moved) {
            claim.reassign(into.getId());
            claim.unbind();
        }
        claims.saveAll(moved);

        // Their name and aliases become the other's aliases; their patrons the other's.
        into.addAlias(from.getName());
        from.getAliases().forEach(into::addAlias);
        for (Long patronId : from.getPatronIds()) {
            if (!patronId.equals(into.getId())) {
                into.addPatron(patronId);
            }
        }
        // Anyone naming them as a patron names the other instead.
        for (Person other : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
            if (other.getId().equals(from.getId()) || !other.removePatron(from.getId())) {
                continue;
            }
            if (!other.getId().equals(into.getId())) {
                other.addPatron(into.getId());
            }
            people.save(other);
        }

        // Their pool memberships move to the other, shares added where the other is already a member.
        for (PoolMember member : poolMembers.findByPersonIdOrderByIdAsc(from.getId())) {
            PoolMember theirs = poolMembers.findByPoolIdAndPersonId(member.getPoolId(), into.getId()).orElse(null);
            if (theirs != null) {
                theirs.addShare(member.getShare());
                poolMembers.save(theirs);
                poolMembers.delete(member);
            } else {
                member.moveTo(into.getId());
                poolMembers.save(member);
            }
        }

        // Their plans become the other's.
        for (Plan plan : plans.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, from.getId())) {
            plan.moveTo(into.getId());
            plans.save(plan);
        }

        // Their statements and watchers are dropped, and they leave the sheet with their holds and contact.
        statements.deleteAll(statements.findBySheetIdAndPersonIdOrderBySeqDesc(sheetId, from.getId()));
        watches.deleteAll(watches.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, from.getId()));
        String fromName = from.getName();
        people.delete(from);
        people.flush();
        Person saved = people.saveAndFlush(into);

        // The moved claims are listed after the other's own, in the order they were added.
        moved.forEach(claim -> claims.relist(claim.getId()));

        audit.recordOnCommit("PERSON_MERGED sheet=" + sheetId + " by=" + user
                + " from=" + fromName + " into=" + saved.getName());
        rollups.audit(sheetId, user, before);
        return people.findByIdAndSheetId(intoId, sheetId).orElseThrow();
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.stream.Stream;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.period.PeriodService;
import net.officefloor.hq.app.pool.PoolMemberRepository;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.rollup.Rollups;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.statement.StatementRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * Transferring a person to another sheet: a steward only. The person arrives on the other sheet with
 * their grades, terms, contact and aliases, and with their claims (status, dates, notes, fixed figures
 * and logs kept); each claim that had a number takes the other sheet's next, in the order the claims
 * were opened, and loses any figure a statement bound and its reference. No statement is counted for
 * them there. They leave this sheet entirely: anyone naming them as a patron no longer does, and their
 * patrons, holds, pool memberships, statements and watchers are dropped. When someone on the other
 * sheet already goes by their name or an alias, they are merged into that person there: their claims
 * listed after the other's own, their name and aliases joined to the other's aliases, and their contact
 * dropped.
 */
@Service
public class TransferService {

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final StatementRepository statements;
    private final WatchRepository watches;
    private final PoolMemberRepository poolMembers;
    private final RoleService roles;
    private final SheetService sheets;
    private final PeriodService periods;
    private final Rollups rollups;
    private final Audit audit;

    public TransferService(PersonRepository people, ClaimRepository claims, StatementRepository statements,
            WatchRepository watches, PoolMemberRepository poolMembers, RoleService roles, SheetService sheets,
            PeriodService periods, Rollups rollups, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.statements = statements;
        this.watches = watches;
        this.poolMembers = poolMembers;
        this.roles = roles;
        this.sheets = sheets;
        this.periods = periods;
        this.rollups = rollups;
        this.audit = audit;
    }

    /**
     * Transfer a person to another sheet by its id. Refused unless the user is a steward on this sheet,
     * for this sheet's own id, for an archived sheet, for a retired person, when their
     * contact is already in use on the other sheet (unless they are merged there), and when the person
     * they would be merged into is retired.
     */
    @Transactional
    public void transfer(String sheetId, String user, long personId, String toSheetId) {
        // Both sheets are locked, always in the same order, so two transfers between them wait in turn.
        Stream.of(sheetId, toSheetId).sorted().forEach(sheets::lock);
        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward transfers people.");
        }
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        if (sheetId.equals(toSheetId)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be transferred to their own sheet.");
        }
        if (sheets.archived(toSheetId)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The other sheet is archived.");
        }
        if (person.getRetiredFrom() != null) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A retired person cannot be transferred.");
        }
        // Someone there going by their name or an alias takes them in, as a merge would.
        Person into = Stream.concat(Stream.of(person.getName()), person.getAliases().stream())
                .map(name -> people.findBySheetIdAndName(toSheetId, name)).flatMap(Optional::stream)
                .findFirst().orElse(null);
        if (into != null && into.getRetiredFrom() != null) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A retired person cannot be merged.");
        }
        if (into == null && person.getContact() != null
                && people.findBySheetIdAndContact(toSheetId, person.getContact()).isPresent()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That contact is already in use on the other sheet.");
        }
        Rollups.Rollup before = rollups.take(sheetId);
        Rollups.Rollup toBefore = rollups.take(toSheetId);

        // Anyone naming them as a patron no longer does; their pool memberships, statements and watchers go.
        for (Person other : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
            if (!other.getId().equals(person.getId()) && other.removePatron(person.getId())) {
                people.save(other);
            }
        }
        poolMembers.deleteAll(poolMembers.findByPersonIdOrderByIdAsc(person.getId()));
        statements.deleteAll(statements.findBySheetIdAndPersonIdOrderBySeqDesc(sheetId, person.getId()));
        watches.deleteAll(watches.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, person.getId()));

        if (into == null) {
            int last = people.findMaxPositionBySheetId(toSheetId);
            person.transferTo(toSheetId);
            person.setPosition(last + 1);
            people.saveAndFlush(person);
        }

        // Their claims follow, each that had a number taking the other sheet's next in the order opened.
        List<Claim> moved = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, person.getId()).stream()
                .sorted(Comparator.comparing((Claim claim) -> claim.openedOn(),
                        Comparator.nullsLast(Comparator.<LocalDate>naturalOrder())).thenComparing(Claim::getId))
                .toList();
        // The numbers are all taken before any claim moves, so none is written there under its old one.
        Map<String, String> numbers = new HashMap<>();
        for (Claim claim : moved) {
            if (claim.getNumber() != null) {
                numbers.put(claim.getNumber(), periods.nextClaimNumber(toSheetId, claim.getDueBy()));
            }
        }
        for (Claim claim : moved) {
            claim.transferTo(toSheetId);
            if (claim.getNumber() != null) {
                claim.number(numbers.get(claim.getNumber()));
            }
            claim.renumberLinks(numbers);
            if (into != null) {
                claim.reassign(into.getId());
            }
        }
        claims.saveAllAndFlush(moved);

        String name = person.getName();
        if (into != null) {
            // Their name and aliases join the other's aliases, and they leave with their holds and contact.
            into.addAlias(name);
            person.getAliases().forEach(into::addAlias);
            people.delete(person);
            people.flush();
            people.saveAndFlush(into);
            // The arriving claims are listed after the other's own, in the order they were added.
            moved.stream().map(Claim::getId).sorted().forEach(claims::relist);
        }
        audit.recordOnCommit("PERSON_TRANSFERRED sheet=" + sheetId + " by=" + user + " name=" + name
                + " to=" + toSheetId);
        rollups.audit(sheetId, user, before);
        audit.recordOnCommit("PERSON_TRANSFERRED sheet=" + toSheetId + " by=" + user + " name=" + name
                + " from=" + sheetId);
        if (into != null) {
            audit.recordOnCommit("PERSON_MERGED sheet=" + toSheetId + " by=" + user + " from=" + name
                    + " into=" + into.getName());
        }
        rollups.audit(toSheetId, user, toBefore);
    }
